import { useEffect } from 'react';
import { ApiFeature } from './ApiFeature';
import { BrandPrinciples } from './BrandPrinciples';
import { EventDerivationStory } from './EventDerivationStory';
import { ExploreGateway } from './ExploreGateway';
import { HomeCallToAction } from './HomeCallToAction';
import { HomeHero } from './HomeHero';

export function HomePage() {
  useEffect(() => {
    document.title = "Stat'sTheGame | T20 cricket analytics";
  }, []);

  return (
    <div className="home-page">
      <HomeHero />
      <BrandPrinciples />
      <EventDerivationStory />
      <ExploreGateway />
      <ApiFeature />
      <HomeCallToAction />
    </div>
  );
}
import { render, screen, within } from '@testing-library/react';
import { MemoryRouter } from 'react-router-dom';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { HomePage } from './HomePage';

function useMotionPreference(reducedMotion: boolean) {
  vi.stubGlobal(
    'matchMedia',
    vi.fn().mockImplementation((query: string) => ({
      matches: query === '(prefers-reduced-motion: reduce)' ? reducedMotion : false,
      media: query,
      onchange: null,
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      addListener: vi.fn(),
      removeListener: vi.fn(),
      dispatchEvent: vi.fn(),
    })),
  );
}

function renderHomePage() {
  render(
    <MemoryRouter>
      <HomePage />
    </MemoryRouter>,
  );
}

describe('homepage', () => {
  beforeEach(() => {
    useMotionPreference(false);
  });

  afterEach(() => {
