import { useCallback, useEffect, useState, type ComponentType } from 'react';
import { Link } from 'react-router-dom';
import { HeroSceneFallback } from './HeroSceneFallback';

interface HeroSceneProps {
  onReady: () => void;
  onUnavailable: () => void;
}

let cachedWebGLSupport: boolean | null = null;

function supportsWebGL(): boolean {
  if (cachedWebGLSupport !== null) {
    return cachedWebGLSupport;
  }

  if (typeof window.WebGLRenderingContext === 'undefined') {
    cachedWebGLSupport = false;
    return false;
  }

  try {
    const canvas = document.createElement('canvas');
    const context = canvas.getContext('webgl2') ?? canvas.getContext('webgl');
    cachedWebGLSupport = context !== null;
  } catch {
    cachedWebGLSupport = false;
  }

  return cachedWebGLSupport;
}

function useReducedMotion(): boolean {
  const [reducedMotion, setReducedMotion] = useState(() =>
    typeof window.matchMedia === 'function'
      ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
      : false,
  );

  useEffect(() => {
    if (typeof window.matchMedia !== 'function') {
      return undefined;
    }

    const query = window.matchMedia('(prefers-reduced-motion: reduce)');
    const handleChange = () => setReducedMotion(query.matches);
    handleChange();
    query.addEventListener('change', handleChange);
    return () => query.removeEventListener('change', handleChange);
  }, []);

  return reducedMotion;
}

export function HomeHero() {
  const reducedMotion = useReducedMotion();
  const [Scene, setScene] = useState<ComponentType<HeroSceneProps> | null>(null);
  const [sceneReady, setSceneReady] = useState(false);
  const handleSceneReady = useCallback(() => setSceneReady(true), []);
  const handleSceneUnavailable = useCallback(() => setSceneReady(false), []);

  useEffect(() => {
    if (reducedMotion) {
      setScene(null);
      setSceneReady(false);
      return undefined;
    }

    let cancelled = false;
    const loadScene = () => {
      void import('./HeroScene')
        .then(({ HeroScene }) => {
          if (!cancelled) {
            setScene(() => HeroScene);
          }
        })
        .catch(() => {
          if (!cancelled) {
            setScene(null);
            setSceneReady(false);
          }
        });
    };

    let idleCallback: number | undefined;
    const loadAfterInteraction = () => {
      if (!supportsWebGL()) {
        setScene(null);
        setSceneReady(false);
        return;
      }
      idleCallback = window.requestIdleCallback?.(loadScene, { timeout: 4_000 });
      if (idleCallback === undefined) {
        loadScene();
      }
    };

    window.addEventListener('pointerdown', loadAfterInteraction, { once: true, passive: true });
    window.addEventListener('keydown', loadAfterInteraction, { once: true });

    return () => {
      cancelled = true;
      if (idleCallback !== undefined) {
        window.cancelIdleCallback?.(idleCallback);
      }
      window.removeEventListener('pointerdown', loadAfterInteraction);
      window.removeEventListener('keydown', loadAfterInteraction);
    };
  }, [reducedMotion]);

  return (
    <section className="home-hero" aria-labelledby="home-title">
      <div className="home-hero__crease" aria-hidden="true" />
      <div className="content-boundary home-hero__layout">
        <div className="home-hero__content">
          <p className="eyebrow">T20 cricket analytics</p>
          <h1 id="home-title">The game, measured ball by ball.</h1>
          <p className="home-hero__summary">
            Explore T20 cricket through the deliveries behind every published statistic, from an
            individual event to its derived value and traceable source.
          </p>
          <div className="home-hero__actions" aria-label="Start exploring">
            <Link className="button button--primary" to="/fixtures">
              Browse fixtures
            </Link>
            <Link className="button button--secondary" to="/competitions">
              Explore competitions
            </Link>
          </div>
          <Link className="home-hero__player-link" to="/participants">
            Browse players <span aria-hidden="true">&#8594;</span>
          </Link>
        </div>

        <div
          className={`home-hero__visual${sceneReady ? ' home-hero__visual--enhanced' : ''}`}
          data-hero-enhancement={sceneReady ? 'three' : 'fallback'}
        >
          <HeroSceneFallback />
          {Scene && !reducedMotion ? (
            <Scene onReady={handleSceneReady} onUnavailable={handleSceneUnavailable} />
          ) : null}
          <div className="home-hero__visual-caption">
            <span>Illustrative delivery</span>
            <strong>Event &#8594; derived values</strong>
          </div>
        </div>
      </div>
    </section>
  );
}

import { useEffect } from 'react';
import { ApiFeature } from './ApiFeature';
import { BrandPrinciples } from './BrandPrinciples';
import { EventDerivationStory } from './EventDerivationStory';
import { ExploreGateway } from './ExploreGateway';
import { HomeCallToAction } from './HomeCallToAction';
import { HomeHero } from './HomeHero';

export function HomePage() {
  useEffect(() => {
    document.title = "Stat'sTheGame | T20 cricket analytics";
  }, []);

  return (
    <div className="home-page">
      <HomeHero />
      <BrandPrinciples />
      <EventDerivationStory />
      <ExploreGateway />
      <ApiFeature />
      <HomeCallToAction />
    </div>
  );
}

import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import process from 'node:process';
import * as chromeLauncher from 'chrome-launcher';
import { chromium } from 'playwright';
import sourceMap from 'source-map';

const baseUrl = process.env.PROFILE_BASE_URL ?? 'http://127.0.0.1:4173';
const outputDirectory = process.env.PROFILE_OUTPUT_DIR ?? 'artifacts/cpu-profile';
const durationMs = Number(process.env.PROFILE_DURATION_MS ?? 5_000);
const { SourceMapConsumer } = sourceMap;

await mkdir(outputDirectory, { recursive: true });

const chrome = await chromeLauncher.launch({
  chromeFlags: ['--headless=new', '--no-first-run', '--no-default-browser-check'],
});
const browser = await chromium.connectOverCDP(`http://127.0.0.1:${chrome.port}`);
try {
  const context = await browser.newContext({ viewport: { width: 1280, height: 720 } });
  const page = await context.newPage();
  const session = await context.newCDPSession(page);
  await session.send('Profiler.enable');
  await session.send('Profiler.start');
  await page.goto(new URL('/', baseUrl).toString(), { waitUntil: 'load' });
  await page.waitForTimeout(durationMs);
  const { profile } = await session.send('Profiler.stop');

  const nodes = new Map(profile.nodes.map((node) => [node.id, node]));
  const totals = new Map();
  for (let index = 1; index < profile.samples.length; index += 1) {
    const node = nodes.get(profile.samples[index]);
    if (!node) continue;
    const frame = node.callFrame;
    const key = `${frame.functionName || '(anonymous)'}\t${frame.url}\t${frame.lineNumber + 1}\t${frame.columnNumber}`;
    totals.set(key, (totals.get(key) ?? 0) + profile.timeDeltas[index]);
  }

  const summary = [...totals.entries()]
    .map(([key, microseconds]) => {
      const [functionName, url, line, column] = key.split('\t');
      return {
        functionName,
        url,
        line: Number(line),
        column: Number(column),
        milliseconds: microseconds / 1_000,
      };
    })
    .sort((left, right) => right.milliseconds - left.milliseconds)
    .slice(0, 50);

  for (const item of summary) {
    if (!item.url.startsWith(baseUrl)) continue;
    const mapPath = path.join(
      'apps/frontend/dist',
      new URL(item.url).pathname.replace(/^\//, '') + '.map',
    );
    try {
      const consumer = await new SourceMapConsumer(JSON.parse(await readFile(mapPath, 'utf8')));
      const original = consumer.originalPositionFor({ line: item.line, column: item.column });
      consumer.destroy?.();
      if (original.source) {
        item.source = original.source;
        item.sourceLine = original.line ?? undefined;
        item.sourceName = original.name ?? undefined;
      }
    } catch {
      // The ordinary production build omits maps; profiling builds provide them.
    }
  }

  await writeFile(path.join(outputDirectory, 'homepage.cpuprofile.json'), JSON.stringify(profile));
  await writeFile(
    path.join(outputDirectory, 'homepage-summary.json'),
    JSON.stringify({ durationMs, samples: profile.samples.length, summary }, null, 2),
  );
  console.table(summary.slice(0, 20));
} finally {
  await browser.close();
  try {
    await chrome.kill();
  } catch (error) {
    if (!(error instanceof Error && 'code' in error && error.code === 'EPERM')) throw error;
  }
}

