);

const ApiExplorerPage = lazy(() =>
  import('./features/api-explorer/ApiExplorerPage').then(({ ApiExplorerPage }) => ({
    default: ApiExplorerPage,
  })),
);

export function PublicApp() {
  return (
    <PublicShell>
