          <Route path="/reviews/batches" element={<BatchReviewWorkspacePage />} />
          <Route path="/reviews/batches/:batchReference" element={<BatchReviewWorkspacePage />} />

          <Route path="*" element={<NotFoundPage />} />
        </Routes>
      </Suspense>
      </div>
    </PublicShell>
  );
}

function App() {
  return <PublicApp />;
}

