+import sourceMap from 'source-map';
+
+const { SourceMapConsumer } = sourceMap;
+const args = process.argv.slice(2);
+const value = (name, fallback) => args.includes(name) ? args[args.indexOf(name) + 1] : fallback;
+
+export const routeSlug = (route) => {
+  if (!route?.startsWith('/') || route.includes('..') || route.includes('\\')) {
+    throw new Error('Use a safe absolute route path.');
+  }
+  return route === '/' ? 'home' : route.replace(/^\/+|\/+$/g, '').replace(/[^a-zA-Z0-9-]+/g, '-');
+};
+
+async function sourceMapFrame(frame, baseUrl) {
+  if (!frame.url.startsWith(baseUrl)) return frame;
+  try {
+    const mapPath = path.join('apps/frontend/dist', new URL(frame.url).pathname.replace(/^\//, '') + '.map');
+    const consumer = await new SourceMapConsumer(JSON.parse(await readFile(mapPath, 'utf8')));
+    const original = consumer.originalPositionFor({ line: frame.line, column: frame.column });
+    consumer.destroy?.();
+    return original.source ? { ...frame, source: original.source, sourceLine: original.line, sourceName: original.name } : frame;
+  } catch {
+    return frame;
+  }
+}
+
+export async function profileRoute({ route = '/', baseUrl = 'http://localhost:5173', output = 'artifacts/cpu-profiles', duration = 5000 } = {}) {
+  const slug = routeSlug(route);
+  await mkdir(output, { recursive: true });
+  const chrome = await chromeLauncher.launch({ chromeFlags: ['--headless=new'] });
+  const browser = await chromium.connectOverCDP(`http://127.0.0.1:${chrome.port}`);
+  try {
+    const context = await browser.newContext({ viewport: { width: 1280, height: 720 } });
+    const page = await context.newPage();
+    await page.addInitScript(() => {
+      window.__cpuTimeline = { fcp: null, lcp: null, element: null, longTasks: [] };
+      new PerformanceObserver((entries) => { for (const entry of entries.getEntries()) if (entry.name === 'first-contentful-paint') window.__cpuTimeline.fcp = entry.startTime; }).observe({ type: 'paint', buffered: true });
+      new PerformanceObserver((entries) => { const entry = entries.getEntries().at(-1); if (entry) { window.__cpuTimeline.lcp = entry.startTime; window.__cpuTimeline.element = entry.element?.outerHTML?.slice(0, 200) ?? null; } }).observe({ type: 'largest-contentful-paint', buffered: true });
+      new PerformanceObserver((entries) => { for (const entry of entries.getEntries()) window.__cpuTimeline.longTasks.push({ startTime: entry.startTime, duration: entry.duration }); }).observe({ type: 'longtask', buffered: true });
+    });
+    const session = await context.newCDPSession(page);
+    await session.send('Profiler.enable');
+    await session.send('Profiler.start');
+    const url = new URL(route, baseUrl).toString();
+    await page.goto(url, { waitUntil: 'load' });
+    await page.waitForTimeout(duration);
+    const { profile } = await session.send('Profiler.stop');
+    const timeline = await page.evaluate(() => window.__cpuTimeline);
+    const nodes = new Map(profile.nodes.map((node) => [node.id, node]));
+    const totals = new Map();
+    let elapsed = 0;
+    for (let index = 1; index < profile.samples.length; index += 1) {
+      elapsed += profile.timeDeltas[index] / 1000;
+      const frame = nodes.get(profile.samples[index])?.callFrame;
+      if (!frame) continue;
+      const key = `${frame.functionName || '(anonymous)'}\t${frame.url}\t${frame.lineNumber + 1}\t${frame.columnNumber}\t${elapsed <= (timeline.lcp ?? Infinity)}`;
+      totals.set(key, (totals.get(key) ?? 0) + profile.timeDeltas[index]);
+    }
+    const summary = await Promise.all([...totals].map(async ([key, microseconds]) => {
+      const [functionName, url, line, column, beforeLcp] = key.split('\t');
+      return sourceMapFrame({ functionName, url, line: Number(line), column: Number(column), beforeLcp: beforeLcp === 'true', milliseconds: microseconds / 1000 }, baseUrl);
+    }));
+    summary.sort((left, right) => right.milliseconds - left.milliseconds);
+    const top = summary.slice(0, 50);
+    const report = { route, baseUrl, url, capturedAt: new Date().toISOString(), duration, timeline, samples: profile.samples.length, totalSampledCpuMs: top.reduce((total, item) => total + item.milliseconds, 0), sourceMapsAvailable: top.some((item) => item.source), summary: top };
