+    console.table(top.slice(0, 20));
+    return report;
+  } finally {
+    await browser.close();
+    await chrome.kill().catch(() => {});
+  }
+}
+
+if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
+  await profileRoute({ route: value('--route', '/'), baseUrl: value('--base-url', process.env.PROFILE_BASE_URL ?? 'http://localhost:5173'), output: value('--output-dir', process.env.PROFILE_OUTPUT_DIR ?? 'artifacts/cpu-profiles'), duration: Number(value('--duration', process.env.PROFILE_DURATION_MS ?? '5000')) });
+}
