const r = await tools.exec_command({"cmd":"$env:PROFILE_JS = @'
const { chromium } = await import("playwright");
const routes = ["/", "/api", "/competitions"];
const browser = await chromium.launch({headless:true});
for (const route of routes) {
  const context = await browser.newContext({ viewport: { width: 412, height: 823 }, deviceScaleFactor: 1.75, isMobile: true, userAgent: "Mozilla/5.0 (Linux; Android 11; moto g power (2022)) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/136.0.0.0 Mobile Safari/537.36" });
  const page = await context.newPage();
  await page.addInitScript(() => {
    window.__timeline = { marks: {}, paints: [], lcps: [], longTasks: [] };
    const mark = (name) => { window.__timeline.marks[name] = performance.now(); };
    document.addEventListener("DOMContentLoaded", () => mark("domContentLoaded"));
    window.addEventListener("load", () => mark("load"));
    document.fonts.ready.then(() => mark("fontsReady"));
    new PerformanceObserver((list) => { for (const entry of list.getEntries()) window.__timeline.paints.push({name:entry.name,start:entry.startTime}); }).observe({type:"paint", buffered:true});
    new PerformanceObserver((list) => { for (const entry of list.getEntries()) window.__timeline.lcps.push({start:entry.startTime, element:entry.element?.outerHTML?.slice(0,180) ?? null, size:entry.size}); }).observe({type:"largest-contentful-paint", buffered:true});
    new PerformanceObserver((list) => { for (const entry of list.getEntries()) window.__timeline.longTasks.push({start:entry.startTime,duration:entry.duration}); }).observe({type:"longtask", buffered:true});
  });
  const cdp = await context.newCDPSession(page);
  await cdp.send("Network.enable");
  await cdp.send("Network.emulateNetworkConditions", { offline:false, latency:562.5, downloadThroughput:184320, uploadThroughput:84375, connectionType:"cellular4g" });
  await cdp.send("Emulation.setCPUThrottlingRate", {rate:4});
  const response = await page.goto("http://127.0.0.1:4175" + route, {waitUntil:"load", timeout:60000});
  await page.waitForTimeout(3500);
  const value = await page.evaluate(() => ({ timeline:window.__timeline, resources:performance.getEntriesByType("resource").filter((x)=>/(woff2|index-.*\.(js|css)|HomePageContent|ApiExplorerPage|PublicBrowsePages)/.test(x.name)).map((x)=>({name:x.name.replace(/^.*\//,""),start:x.startTime,end:x.responseEnd,transfer:x.transferSize,initiator:x.initiatorType})), h1:document.querySelector("h1")?.outerHTML?.slice(0,200), fonts:[...document.fonts].map((font)=>({family:font.family,weight:font.weight,status:font.status})) }));
  console.log(JSON.stringify({route,status:response?.status(),...value},null,2));
  await context.close();
}
await browser.close();
