.site-header {
  position: relative;
  z-index: 10;
  border-bottom: 1px solid var(--colour-border);
  background: var(--colour-surface);
  box-shadow: var(--shadow-header);
}

.site-header__inner,
.site-footer__inner,
.content-boundary {
  width: min(100% - 3rem, 100rem);
  margin-inline: auto;
}

.site-header__inner {
  min-height: 5.5rem;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 1.5rem;
}

.site-header__controls,
.auth-navigation,
.auth-navigation-wrap {
  display: flex;
  align-items: center;
}

.site-header__controls {
  justify-content: flex-end;
  gap: 1.5rem;
}

.auth-navigation-wrap {
  position: relative;
