  place-items: center;
  padding-block: 4rem;
}

.auth-card {
  width: min(100%, 47.5rem);
  padding: 3rem;
  border: 1px solid var(--colour-border);
  border-radius: 10px;
  background: var(--colour-surface);
  box-shadow: var(--shadow-header);
}

.auth-card h1 {
  font-size: clamp(2.5rem, 8vw, 3.5rem);
  white-space: normal;
}
}

.site-footer__navigation a:hover {
  color: var(--colour-text);
  text-decoration: underline;
}

.browse-page {
  min-height: 38rem;
  padding-bottom: 5rem;
}

.page-heading {
  padding-block: 2rem 1.5rem;
}

.page-heading h1 {
  max-width: 20ch;
  margin: 0;
  font-size: 3.25rem;
  line-height: 1;
  white-space: normal;
